using FlaUI.Core.AutomationElements;
using FlaUI.Core.Definitions;
using FlaUI.Core.WindowsAPI;

namespace Humcp.App.UiTests;

/// <summary>
/// The shell (ROADMAP §10, Phase 6): servers added, edited and removed from the keyboard and kept
/// in a file, humcp's own forms generated by its own engine, a tool list that changes under the
/// user, a grid that sorts and says so, and a route to resizing the panes.
/// </summary>
[Collection(AppCollection.Name)]
public class ShellTests(AppFixture fixture, ITestOutputHelper output)
{
    private Window Main => fixture.Window;

    // ------------------------------------------------------------------ adding and removing

    [Fact]
    public void A_server_added_from_the_keyboard_is_saved_connected_and_removable()
    {
        const string Name = "Second fixture";
        var located = Humcp.Tests.TestServerLocator.Locate(AppContext.BaseDirectory)!.Value;

        Input.EnsureForeground(Main, fixture.Automation);
        Input.Press(VirtualKeyShort.CONTROL, VirtualKeyShort.KEY_N);

        var form = fixture.Owned("Add a server", TimeSpan.FromSeconds(10));
        Assert.True(form is not null, "Control plus N opened no Add a server window. Open: " + string.Join(", ", fixture.Titles()));

        try
        {
            // Setup through the Value pattern: the keyboard is for the assertions about it (§9).
            SetText(form!, "Name", Name);
            SetText(form!, "Command", located.Command);
            SetText(form!, "Arguments", string.Join(' ', located.Arguments.Select(a => a.Contains(' ') ? $"\"{a}\"" : a)));

            form!.FindFirstDescendant(cf => cf.ByAutomationId("AddServerSave"))!.AsButton().Invoke();

            var node = WaitFor(() => ServerNode(Name, "connected"), $"{Name} to connect");
            output.WriteLine(node.Name);

            // In the file the user owns, under the shape every other client reads.
            Assert.Contains($"\"{Name}\"", File.ReadAllText(fixture.ConfigurationPath));
        }
        finally
        {
            try { form?.Close(); } catch { /* already closed by saving */ }
        }

        // Removed with Delete, asked twice: the first press says what will go and does nothing.
        Input.EnsureForeground(Main, fixture.Automation);
        var server = ServerNode(Name, "")!;
        server.Patterns.SelectionItem.Pattern.Select();
        server.Focus();
        Input.Settle(200);

        Input.Press(VirtualKeyShort.DELETE);
        WaitFor(() => Status().StartsWith("Press Delete again", StringComparison.Ordinal) ? Status() : null,
            "the first Delete to ask again");
        Assert.NotNull(ServerNode(Name, ""));

        Input.Press(VirtualKeyShort.DELETE);
        WaitFor(() => ServerNode(Name, "") is null ? "gone" : null, $"{Name} to be removed");

        Assert.DoesNotContain($"\"{Name}\"", File.ReadAllText(fixture.ConfigurationPath));

        // The caret is somewhere a reader can say, not on the window (§7.25).
        Input.Settle(300);
        Assert.Equal(ControlType.TreeItem, UiaTree.Safe(() => fixture.Automation.FocusedElement()?.ControlType));
    }

    [Fact]
    public void Humcp_s_own_form_keeps_the_contract_every_generated_form_keeps()
    {
        Input.EnsureForeground(Main, fixture.Automation);
        Input.Press(VirtualKeyShort.CONTROL, VirtualKeyShort.KEY_N);

        var form = fixture.Owned("Add a server", TimeSpan.FromSeconds(10));
        Assert.NotNull(form);

        try
        {
            var fields = form!.FindFirstDescendant(cf => cf.ByAutomationId("AddServerFields"))!;

            // §7.12: a group of groups, not a list of data items.
            Assert.Equal(ControlType.Group, fields.ControlType);
            Assert.DoesNotContain(UiaTree.Descendants(fields), e => UiaTree.Safe(() => e.ControlType) == ControlType.DataItem);

            // Nothing hidden: every field here is saved, so every field is on screen (§7.31).
            foreach (var label in new[] { "Name", "Command", "Arguments", "Working directory", "Environment variables", "Start this server" })
                Assert.True(Control(form, label) is not null, $"No control named {label}.");

            Assert.True(Control(form, "Name")!.Properties.IsRequiredForForm.ValueOrDefault);
            Assert.True(Control(form, "Command")!.Properties.IsRequiredForForm.ValueOrDefault);
            Assert.False(Control(form, "Arguments")!.Properties.IsRequiredForForm.ValueOrDefault);

            // The caret starts on the first field, not on the window.
            Input.Settle(300);
            Assert.Equal("Name", UiaTree.Safe(() => fixture.Automation.FocusedElement()?.Name));

            var save = form.FindFirstDescendant(cf => cf.ByAutomationId("AddServerSave"))!;
            Assert.Equal("Control plus Enter", save.Properties.AcceleratorKey.ValueOrDefault);
        }
        finally
        {
            form?.Close();
            Input.Settle(300);
        }
    }

    [Fact]
    public void An_empty_add_server_form_refuses_to_save_and_says_why()
    {
        Input.EnsureForeground(Main, fixture.Automation);
        Input.Press(VirtualKeyShort.CONTROL, VirtualKeyShort.KEY_N);

        var form = fixture.Owned("Add a server", TimeSpan.FromSeconds(10));
        Assert.NotNull(form);

        try
        {
            Input.Settle(300);
            Input.Press(VirtualKeyShort.CONTROL, VirtualKeyShort.RETURN);
            Input.Settle(400);

            // Still open — this schema is humcp's own, so here validation is the authority.
            Assert.True(UiaTree.Safe(() => form!.IsAvailable));

            var status = form!.FindFirstDescendant(cf => cf.ByAutomationId("AddServerStatus"))?.Name ?? "";
            output.WriteLine(status);
            Assert.Contains("to fix before this can be saved", status);
        }
        finally
        {
            form?.Close();
            Input.Settle(300);
        }
    }

    [Fact]
    public void Settings_open_from_the_keyboard_as_three_named_check_boxes()
    {
        Input.EnsureForeground(Main, fixture.Automation);
        Input.Press(VirtualKeyShort.CONTROL, VirtualKeyShort.OEM_COMMA);

        var form = fixture.Owned("Settings", TimeSpan.FromSeconds(10));
        Assert.True(form is not null, "Control plus Comma opened no Settings window.");

        try
        {
            foreach (var label in new[]
                     {
                         "Show optional parameters when a form opens",
                         "Remember what is typed into forms",
                         "Speak when humcp is in the background",
                     })
            {
                var box = Control(form!, label);
                Assert.True(box is not null, $"No check box named {label}.");
                Assert.Equal(ControlType.CheckBox, box!.ControlType);
            }
        }
        finally
        {
            form?.Close();
            Input.Settle(300);
        }
    }

    // ------------------------------------------------------------------ the list changing

    [Fact]
    public void A_tool_that_appears_on_the_server_appears_in_the_tree()
    {
        RunZeroArgument("Add or remove a tool");

        try
        {
            WaitFor(() => Tree().FindAllDescendants(cf => cf.ByControlType(ControlType.TreeItem))
                    .FirstOrDefault(i => (UiaTree.Safe(() => i.Name) ?? "").StartsWith("A tool that appeared", StringComparison.Ordinal)),
                "the new tool to reach the tree");

            output.WriteLine(Status());
        }
        finally
        {
            // Put the server back, so the rest of the suite counts the tools it expects.
            RunZeroArgument("Add or remove a tool");
            WaitFor(() => Tree().FindAllDescendants(cf => cf.ByControlType(ControlType.TreeItem))
                    .Any(i => (UiaTree.Safe(() => i.Name) ?? "").StartsWith("A tool that appeared", StringComparison.Ordinal))
                    ? null : "gone",
                "the new tool to leave the tree");
        }
    }

    // ------------------------------------------------------------------ sorting

    [Fact]
    public void A_column_header_sorts_the_grid_and_the_header_says_so()
    {
        var window = OpenForm("Table of entities", "Table of entities — humcp test server");

        try
        {
            window.FindFirstDescendant(cf => cf.ByAutomationId("FormRunButton"))!.AsButton().Invoke();

            var grid = WaitFor(() => window.FindFirstDescendant(cf => cf.ByControlType(ControlType.DataGrid)),
                "a grid in the form's result pane");

            var header = WaitFor(() => grid.FindFirstDescendant(cf => cf.ByControlType(ControlType.Header)), "the header row");
            var observations = UiaTree.Children(header).First(h => UiaTree.Safe(() => h.Name) == "Observations");

            observations.Patterns.Invoke.Pattern.Invoke();

            WaitFor(() => UiaTree.Children(header).FirstOrDefault(h => UiaTree.Safe(() => h.Name) == "Observations, sorted ascending"),
                "the header to say it is sorted");

            var status = WaitFor(() => window.FindFirstDescendant(cf => cf.ByAutomationId("FormStatus"))?.Name is { } s
                                       && s.StartsWith("Sorted by", StringComparison.Ordinal) ? s : null,
                "the sort to be announced");

            Assert.Equal("Sorted by Observations, ascending.", status);
        }
        finally
        {
            window.Close();
            Input.Settle(300);
        }
    }

    // ------------------------------------------------------------------ resizing

    [Fact]
    public void The_panes_can_be_resized_from_the_keyboard()
    {
        Input.EnsureForeground(Main, fixture.Automation);

        var item = UiaTree.Children(Tree()).First();
        item.Patterns.SelectionItem.Pattern.Select();
        item.Focus();
        Input.Settle(200);

        Input.Press(VirtualKeyShort.ALT, VirtualKeyShort.KEY_V);
        Input.Settle(200);
        Input.Press(VirtualKeyShort.KEY_W);

        var form = fixture.Owned("Servers pane width", TimeSpan.FromSeconds(10));
        Assert.True(form is not null, "View, Servers pane width opened no window. Open: " + string.Join(", ", fixture.Titles()));

        var splitter = Main.FindFirstDescendant(cf => cf.ByName("Resize servers pane"))!;
        var before = splitter.BoundingRectangle.Left;

        try
        {
            // Fitted by default, so a percentage means unticking that first.
            var fit = Control(form!, "Fit the servers pane to what is in it")!.AsCheckBox();
            Assert.True(fit.IsChecked);
            fit.Toggle();

            SetText(form!, "Servers pane width, in percent", "60");
            form!.FindFirstDescendant(cf => cf.ByAutomationId("PaneWidthSave"))!.AsButton().Invoke();

            var status = WaitFor(() => Status().StartsWith("The servers pane is", StringComparison.Ordinal) ? Status() : null,
                "the new width to be announced");
            output.WriteLine(status);

            Assert.Equal("The servers pane is 60 percent of the width.", status);
            Assert.True(splitter.BoundingRectangle.Left > before, "The divider did not move right.");
        }
        finally
        {
            try { form?.Close(); } catch { /* closed by saving */ }
        }

        // And the divider is not a stop for the keyboard at all now: it is the mouse's route.
        Assert.False(splitter.Properties.IsKeyboardFocusable.ValueOrDefault);

        // Fitting back on, which is also what puts the app back as the rest of the suite expects.
        Input.EnsureForeground(Main, fixture.Automation);
        Input.Press(VirtualKeyShort.ALT, VirtualKeyShort.KEY_V);
        Input.Settle(200);
        Input.Press(VirtualKeyShort.KEY_W);

        var again = fixture.Owned("Servers pane width", TimeSpan.FromSeconds(10))!;
        try
        {
            var fit = Control(again, "Fit the servers pane to what is in it")!.AsCheckBox();
            Assert.False(fit.IsChecked);
            fit.Toggle();
            again.FindFirstDescendant(cf => cf.ByAutomationId("PaneWidthSave"))!.AsButton().Invoke();

            var status = WaitFor(() => Status().StartsWith("The servers pane fits", StringComparison.Ordinal) ? Status() : null,
                "fitting to be announced");
            output.WriteLine(status);
            // Half the window plus the window's own margin and border, which the panes do not share.
            Assert.True(splitter.BoundingRectangle.Left <= Main.BoundingRectangle.Left + Main.BoundingRectangle.Width / 2 + 24,
                $"A fitted pane is never more than half the window: divider at {splitter.BoundingRectangle.Left}, window {Main.BoundingRectangle}.");
        }
        finally
        {
            try { again.Close(); } catch { /* closed by saving */ }
        }
    }

    // ------------------------------------------------------------------ helpers

    private AutomationElement Tree() =>
        Main.FindFirstDescendant(cf => cf.ByControlType(ControlType.Tree))
        ?? throw new InvalidOperationException("The main window has no tree.");

    private AutomationElement? ServerNode(string name, string state) =>
        UiaTree.Children(Tree()).FirstOrDefault(i =>
            (UiaTree.Safe(() => i.Name) ?? "") is var n
            && n.StartsWith(name + ",", StringComparison.Ordinal)
            && n.Contains(state, StringComparison.Ordinal));

    private string Status() => Main.FindFirstDescendant(cf => cf.ByAutomationId("LiveStatus"))?.Name ?? "";

    private static AutomationElement? Control(Window window, string label) =>
        UiaTree.Descendants(window).LastOrDefault(e =>
            UiaTree.Safe(() => e.Name) == label
            && UiaTree.Safe(() => e.Properties.IsKeyboardFocusable.ValueOrDefault) == true);

    private static void SetText(Window window, string label, string value)
    {
        var box = Control(window, label) ?? throw new InvalidOperationException($"No box named {label}.");
        box.Patterns.Value.Pattern.SetValue(value);
        Input.Settle(100);
    }

    private void RunZeroArgument(string label)
    {
        var tool = Tree().FindAllDescendants(cf => cf.ByControlType(ControlType.TreeItem))
            .First(i => (UiaTree.Safe(() => i.Name) ?? "").StartsWith(label, StringComparison.Ordinal));

        tool.Patterns.SelectionItem.Pattern.Select();
        Input.Settle(150);

        var run = Main.FindFirstDescendant(cf => cf.ByAutomationId("RunButton"))!.AsButton();
        WaitFor(() => UiaTree.Safe(() => run.IsEnabled) == true ? "enabled" : null, "the Run button");
        run.Invoke();

        WaitFor(() => Main.FindFirstDescendant(cf => cf.ByAutomationId("ResultHeading"))?.Name is { } h
                      && h.StartsWith($"Result — {label}", StringComparison.Ordinal) ? h : null,
            $"{label} to finish");
    }

    private Window OpenForm(string toolLabel, string windowTitle)
    {
        if (fixture.Owned(windowTitle, TimeSpan.FromMilliseconds(200)) is { } already) return already;

        var tool = Tree().FindAllDescendants(cf => cf.ByControlType(ControlType.TreeItem))
            .First(i => (UiaTree.Safe(() => i.Name) ?? "").StartsWith(toolLabel, StringComparison.Ordinal));
        tool.Patterns.SelectionItem.Pattern.Select();
        Input.Settle(150);

        var run = Main.FindFirstDescendant(cf => cf.ByAutomationId("RunButton"))!.AsButton();
        WaitFor(() => UiaTree.Safe(() => run.IsEnabled) == true ? "enabled" : null, "the Run button");
        run.Invoke();

        var window = fixture.Owned(windowTitle, TimeSpan.FromSeconds(10));
        Assert.True(window is not null, $"The form window {windowTitle} did not open.");

        Input.Settle(300);
        return window!;
    }

    private static T WaitFor<T>(Func<T?> read, string what) where T : class
    {
        var deadline = DateTime.UtcNow + TimeSpan.FromSeconds(30);

        while (DateTime.UtcNow < deadline)
        {
            var value = UiaTree.Safe(read);
            if (value is not null) return value;
            Thread.Sleep(150);
        }

        throw new InvalidOperationException($"Waited thirty seconds for {what} and it never happened.");
    }
}
